(function () { var items = document.querySelectorAll('.faq__item'); if (!items.length) return; items.forEach(function (item) { var btn = item.querySelector('.faq__question'); var answer = item.querySelector('.faq__answer'); var inner = item.querySelector('.faq__answer-inner'); btn.addEventListener('click', function () { var isOpen = item.classList.contains('is-open'); items.forEach(function (other) { if (other !== item) { other.classList.remove('is-open'); other.querySelector('.faq__question').setAttribute('aria-expanded', 'false'); other.querySelector('.faq__answer').style.maxHeight = '0'; } }); if (isOpen) { item.classList.remove('is-open'); btn.setAttribute('aria-expanded', 'false'); answer.style.maxHeight = '0'; } else { item.classList.add('is-open'); btn.setAttribute('aria-expanded', 'true'); answer.style.maxHeight = inner.scrollHeight + 'px'; } }); }); })();